import 'package:flutter/material.dart';
class StatusIcons extends StatelessWidget{final List<dynamic> icons;const StatusIcons({super.key,required this.icons});@override Widget build(BuildContext c)=>Row(mainAxisSize:MainAxisSize.min,children:icons.map((x){final v='$x';final d=switch(v){'accident'=>(Icons.warning_rounded,const Color(0xFF7B3FF2)),'pending'=>(Icons.hourglass_top_rounded,const Color(0xFFE53935)),'in_progress'=>(Icons.build_circle_rounded,const Color(0xFFF28C28)),'vidange'=>(Icons.handyman_rounded,const Color(0xFF6D4C41)),_=>(Icons.check_circle_rounded,const Color(0xFF2E7D32))};return Padding(padding:const EdgeInsetsDirectional.only(start:4),child:Icon(d.$1,color:d.$2,size:21));}).toList());}}
